import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Button, Modal, Form } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { toast } from 'react-toastify';
import { bpmnAPI, adminAPI } from '../../services/api'; // Import bpmnAPI yang baru
import { getUser } from '../../utils/auth';

const AdminDashboard = () => {
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
    zoomAvailable: 0
  });
  const [recentRequests, setRecentRequests] = useState([]);
  const [zoomLinks, setZoomLinks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showApproveModal, setShowApproveModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [selectedZoomId, setSelectedZoomId] = useState('');
  const [rejectionReason, setRejectionReason] = useState('');
  const [adminNotes, setAdminNotes] = useState('');
  const user = getUser();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        const dashboardRes = await bpmnAPI.getAdminItDashboard();
        const zoomRes = await adminAPI.getZoomLinks();
        
        const { stats: dashboardStats, recentRequests: recentReq } = dashboardRes.data;
        const zooms = zoomRes.data;
        
        setStats({
          total: dashboardStats.total_requests || 0,
          pending: dashboardStats.pending_requests || 0,
          approved: dashboardStats.validated_requests || 0,
          rejected: dashboardStats.rejected_requests || 0,
          zoomAvailable: zooms.filter(z => z.is_active).length
        });
        
        // Filter requests untuk Admin IT - hanya zoom dan both
        const adminRelevantRequests = (recentReq || []).filter(request => 
          request.request_type === 'zoom' || request.request_type === 'both'
        );
        
        setRecentRequests(adminRelevantRequests);
        setZoomLinks(zooms);
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        
        // Fallback ke API lama dengan error handling
        try {
          const [requestsRes, zoomRes] = await Promise.all([
            adminAPI.getAllRequests(),
            adminAPI.getZoomLinks()
          ]);

          console.log('📋 Requests response:', requestsRes);
          console.log('🔗 Zoom response:', zoomRes);

          // Handle requests data with validation
          let requests = [];
          if (requestsRes.data) {
            if (Array.isArray(requestsRes.data)) {
              requests = requestsRes.data;
            } else if (requestsRes.data.data && Array.isArray(requestsRes.data.data)) {
              requests = requestsRes.data.data;
            }
          }

          // Handle zoom links data with validation
          let zooms = [];
          if (zoomRes.data) {
            if (Array.isArray(zoomRes.data)) {
              zooms = zoomRes.data;
            } else if (zoomRes.data.data && Array.isArray(zoomRes.data.data)) {
              zooms = zoomRes.data.data;
            }
          }

          // Ensure both are arrays
          if (!Array.isArray(requests)) {
            console.warn('⚠️ Requests is not an array, setting to empty array');
            requests = [];
          }

          if (!Array.isArray(zooms)) {
            console.warn('⚠️ Zooms is not an array, setting to empty array');
            zooms = [];
          }

          console.log('📊 Processed requests:', requests);
          console.log('🔗 Processed zooms:', zooms);

          // Calculate stats
          const stats = {
            total: requests.length,
            pending: requests.filter(r => r.status === 'pending').length,
            approved: requests.filter(r => r.status === 'approved').length,
            rejected: requests.filter(r => r.status === 'rejected').length,
            zoomAvailable: zooms.filter(z => z.is_active).length
          };

          setStats(stats);
          
          // Filter requests untuk Admin IT - hanya zoom dan both
          const adminRelevantRequests = requests.filter(request => 
            request.request_type === 'zoom' || request.request_type === 'both'
          );
          
          setRecentRequests(adminRelevantRequests.slice(0, 5));
          setZoomLinks(zooms);
          
        } catch (fallbackError) {
          console.error('❌ Fallback also failed:', fallbackError);
          
          // Set empty data on complete failure
          setStats({
            total: 0,
            pending: 0,
            approved: 0,
            rejected: 0,
            zoomAvailable: 0
          });
          setRecentRequests([]);
          setZoomLinks([]);
          
          toast.error('Gagal memuat data dashboard');
        }
      }
      
    } catch (error) {
      console.error('Error fetching admin dashboard data:', error);
      toast.error('Gagal memuat data dashboard');
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = (request) => {
    setSelectedRequest(request);
    if (request.request_type === 'zoom' || request.request_type === 'both') {
      setShowApproveModal(true);
    } else {
      // Direct approve for room only
      submitApprove(request.id, null);
    }
  };

  const handleReject = (request) => {
    setSelectedRequest(request);
    setShowRejectModal(true);
  };

  const submitApprove = async (requestId, zoomLinkId) => {
    try {
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        const data = {
          action: 'approve'
        };
        if (zoomLinkId) {
          data.zoom_link_id = zoomLinkId;
        }
        if (adminNotes.trim()) {
          data.admin_notes = adminNotes.trim();
        }
        
        await bpmnAPI.adminItValidateRequest(requestId, data);
        
        // Berikan pesan yang spesifik berdasarkan jenis request
        if (selectedRequest.request_type === 'zoom') {
          toast.success('✅ Zoom request berhasil disetujui dan diselesaikan!');
        } else if (selectedRequest.request_type === 'both') {
          toast.success('✅ Zoom disetujui, request diteruskan ke Logistik untuk approval ruangan!');
        } else {
          toast.success('✅ Request divalidasi dan diteruskan ke Logistik!');
        }
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        // Fallback ke API lama
        const data = zoomLinkId ? { zoom_link_id: zoomLinkId } : {};
        if (adminNotes.trim()) {
          data.admin_notes = adminNotes.trim();
        }
        await adminAPI.approveRequest(requestId, data);
        toast.success('Request berhasil disetujui!');
      }
      
      fetchDashboardData();
      setShowApproveModal(false);
      setSelectedZoomId('');
      setAdminNotes('');
    } catch (error) {
      console.error('Error approving request:', error);
      toast.error('Gagal menyetujui request');
    }
  };

  const submitReject = async () => {
    if (!rejectionReason.trim()) {
      toast.error('Alasan penolakan harus diisi');
      return;
    }

    try {
      // Coba menggunakan BPMN API terlebih dahulu
      try {
        await bpmnAPI.adminItValidateRequest(selectedRequest.id, {
          action: 'reject',
          reason: rejectionReason
        });
        toast.success('Request berhasil ditolak!');
        
      } catch (bpmnError) {
        console.log('BPMN API not ready, using fallback...');
        // Fallback ke API lama
        await adminAPI.rejectRequest(selectedRequest.id, {
          rejection_reason: rejectionReason
        });
        toast.success('Request berhasil ditolak!');
      }
      
      fetchDashboardData();
      setShowRejectModal(false);
      setRejectionReason('');
    } catch (error) {
      console.error('Error rejecting request:', error);
      toast.error('Gagal menolak request');
    }
  };

  const getStatusBadge = (status) => {
    const variants = {
      pending: 'warning',
      approved: 'success',
      rejected: 'danger'
    };
    return <Badge bg={variants[status]}>{status.toUpperCase()}</Badge>;
  };

  const getTypeBadge = (type) => {
    const variants = {
      room: 'info',
      zoom: 'primary',
      both: 'success'
    };
    const labels = {
      room: 'Ruangan',
      zoom: 'Zoom',
      both: 'Ruangan + Zoom'
    };
    return <Badge bg={variants[type]}>{labels[type]}</Badge>;
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Dashboard Admin IT</h2>
          <p className="text-muted">Selamat datang, {user?.name || user?.email}!</p>
        </Col>
        <Col xs="auto">
          <Button as={Link} to="/admin/zoom" variant="primary" className="me-2">
            <i className="fas fa-video me-2"></i>
            Kelola Zoom
          </Button>
          <Button as={Link} to="/admin/bookings" variant="outline-primary">
            <i className="fas fa-list me-2"></i>
            Semua Booking
          </Button>
        </Col>
      </Row>

      {/* Role Information */}
      <Row className="mb-4">
        <Col>
          <div className="alert alert-info">
            <i className="fas fa-info-circle me-2"></i>
            <strong>Role Admin IT:</strong> Anda bertanggung jawab untuk memvalidasi request dan mengelola zoom. 
            Request <strong>zoom-only</strong> akan langsung diselesaikan oleh Anda. 
            Request yang membutuhkan <strong>ruangan</strong> akan diteruskan ke Logistik setelah validasi.
          </div>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col md={2}>
          <Card className="text-center h-100 border-primary">
            <Card.Body>
              <i className="fas fa-calendar-alt fa-2x text-primary mb-2"></i>
              <h3>{stats.total}</h3>
              <p className="text-muted mb-0">Total Request</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-warning">
            <Card.Body>
              <i className="fas fa-clock fa-2x text-warning mb-2"></i>
              <h3>{stats.pending}</h3>
              <p className="text-muted mb-0">Pending</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-success">
            <Card.Body>
              <i className="fas fa-check-circle fa-2x text-success mb-2"></i>
              <h3>{stats.approved}</h3>
              <p className="text-muted mb-0">Approved</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-danger">
            <Card.Body>
              <i className="fas fa-times-circle fa-2x text-danger mb-2"></i>
              <h3>{stats.rejected}</h3>
              <p className="text-muted mb-0">Rejected</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={2}>
          <Card className="text-center h-100 border-info">
            <Card.Body>
              <i className="fas fa-video fa-2x text-info mb-2"></i>
              <h3>{stats.zoomAvailable}</h3>
              <p className="text-muted mb-0">Zoom Tersedia</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Requests */}
      <Row>
        <Col>
          <Card>
            <Card.Header className="d-flex justify-content-between align-items-center">
              <h5 className="mb-0">Request Terbaru</h5>
              <Button as={Link} to="/admin/bookings" variant="outline-primary" size="sm">
                Lihat Semua
              </Button>
            </Card.Header>
            <Card.Body>
              {recentRequests.length > 0 ? (
                <Table responsive>
                  <thead>
                    <tr>
                      <th>User</th>
                      <th>Judul</th>
                      <th>Tanggal</th>
                      <th>Waktu</th>
                      <th>Jenis</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentRequests.map((request) => (
                      <tr key={request.id}>
                        <td>{request.user_email}</td>
                        <td>{request.title}</td>
                        <td>{new Date(request.date).toLocaleDateString('id-ID')}</td>
                        <td>{request.start_time} - {request.end_time}</td>
                        <td>{getTypeBadge(request.request_type)}</td>
                        <td>{getStatusBadge(request.status)}</td>
                        <td>
                          {request.status === 'pending' && (
                            <div className="btn-group">
                              {/* Admin IT hanya bisa handle zoom dan both (untuk bagian zoom) */}
                              {(request.request_type === 'zoom' || request.request_type === 'both') && (
                                <>
                                  <Button
                                    variant="success"
                                    size="sm"
                                    onClick={() => handleApprove(request)}
                                    title="Approve Zoom"
                                  >
                                    <i className="fas fa-check"></i>
                                  </Button>
                                  <Button
                                    variant="danger"
                                    size="sm"
                                    onClick={() => handleReject(request)}
                                    title="Reject Request"
                                  >
                                    <i className="fas fa-times"></i>
                                  </Button>
                                </>
                              )}
                              {/* Untuk request room-only, admin tidak bisa approve */}
                              {request.request_type === 'room' && (
                                <Badge bg="secondary">
                                  Hanya untuk Logistik
                                </Badge>
                              )}
                            </div>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-4">
                  <i className="fas fa-inbox fa-3x text-muted mb-3"></i>
                  <p className="text-muted">Tidak ada request terbaru</p>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Approve Modal */}
      <Modal show={showApproveModal} onHide={() => setShowApproveModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>
            {selectedRequest?.request_type === 'zoom' ? 'Approve Zoom Request' :
             selectedRequest?.request_type === 'both' ? 'Validate Request & Approve Zoom' :
             'Validate Request'}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <div className="alert alert-info">
                <i className="fas fa-info-circle me-2"></i>
                <strong>Admin IT Role:</strong> 
                {selectedRequest.request_type === 'zoom' && 
                  ' Anda akan meng-approve zoom dan menyelesaikan request.'
                }
                {selectedRequest.request_type === 'both' && 
                  ' Anda akan meng-approve zoom dan meneruskan ke logistik untuk approval ruangan.'
                }
                {selectedRequest.request_type === 'room' && 
                  ' Request ini hanya untuk ruangan, akan langsung diteruskan ke logistik.'
                }
              </div>
              
              <p>Detail request:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedRequest.title}</li>
                <li><strong>User:</strong> {selectedRequest.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
                <li><strong>Waktu:</strong> {selectedRequest.start_time} - {selectedRequest.end_time}</li>
                <li><strong>Jenis:</strong> 
                  {selectedRequest.request_type === 'zoom' && <Badge bg="primary">Zoom Only</Badge>}
                  {selectedRequest.request_type === 'room' && <Badge bg="success">Room Only</Badge>}
                  {selectedRequest.request_type === 'both' && <Badge bg="warning">Zoom + Room</Badge>}
                </li>
              </ul>

              {(selectedRequest.request_type === 'zoom' || selectedRequest.request_type === 'both') && (
                <Form.Group className="mt-3">
                  <Form.Label>Pilih Zoom Account:</Form.Label>
                  <Form.Select
                    value={selectedZoomId}
                    onChange={(e) => setSelectedZoomId(e.target.value)}
                    required
                  >
                    <option value="">-- Pilih Zoom Account --</option>
                    {zoomLinks.filter(z => z.is_active).map(zoom => (
                      <option key={zoom.id} value={zoom.id}>
                        {zoom.zoom_account_name} ({zoom.zoom_email})
                      </option>
                    ))}
                  </Form.Select>
                </Form.Group>
              )}

              <Form.Group className="mt-3">
                <Form.Label>Catatan untuk User (Opsional):</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={adminNotes}
                  onChange={(e) => setAdminNotes(e.target.value)}
                  placeholder="Berikan catatan atau informasi tambahan untuk user..."
                />
                <Form.Text className="text-muted">
                  Catatan ini akan dilihat oleh user dan admin lainnya.
                </Form.Text>
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowApproveModal(false)}>
            Batal
          </Button>
          <Button 
            variant="success" 
            onClick={() => submitApprove(selectedRequest?.id, selectedZoomId || null)}
            disabled={
              (selectedRequest?.request_type === 'zoom' || selectedRequest?.request_type === 'both') 
              && !selectedZoomId
            }
          >
            {selectedRequest?.request_type === 'zoom' ? 'Approve Zoom' :
             selectedRequest?.request_type === 'both' ? 'Validate & Approve Zoom' :
             'Validate Request'}
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Reject Modal */}
      <Modal show={showRejectModal} onHide={() => setShowRejectModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Tolak Request</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {selectedRequest && (
            <>
              <p>Anda akan menolak request:</p>
              <ul>
                <li><strong>Judul:</strong> {selectedRequest.title}</li>
                <li><strong>User:</strong> {selectedRequest.user_email}</li>
                <li><strong>Tanggal:</strong> {new Date(selectedRequest.date).toLocaleDateString('id-ID')}</li>
              </ul>

              <Form.Group className="mt-3">
                <Form.Label>Alasan Penolakan:</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  placeholder="Jelaskan alasan penolakan..."
                  required
                />
              </Form.Group>
            </>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowRejectModal(false)}>
            Batal
          </Button>
          <Button variant="danger" onClick={submitReject}>
            Tolak
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default AdminDashboard;
